SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `areas`;
CREATE TABLE `areas` (
  `area_id` int(11) NOT NULL AUTO_INCREMENT,
  `area_name` varchar(100) NOT NULL,
  `area_block` varchar(50) DEFAULT NULL,
  `area_lot` varchar(50) DEFAULT NULL,
  `area_description` text DEFAULT NULL,
  `area_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `area_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `area_market_id` int(11) NOT NULL,
  PRIMARY KEY (`area_id`),
  UNIQUE KEY `area_name` (`area_name`),
  KEY `idx_areas_market` (`area_market_id`),
  CONSTRAINT `fk_areas_market` FOREIGN KEY (`area_market_id`) REFERENCES `markets` (`market_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `bills`;
CREATE TABLE `bills` (
  `bill_id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_contract_id` int(11) NOT NULL,
  `bill_code` varchar(50) NOT NULL,
  `bill_invoice_date` date NOT NULL,
  `bill_due_date` date NOT NULL,
  `bill_rent_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_electric_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_water_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_management_fee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_sanitation_fee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_security_fee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_other_fee` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_total_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_paid_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bill_status` varchar(20) NOT NULL DEFAULT 'unpaid',
  `bill_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `bill_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`bill_id`),
  UNIQUE KEY `bill_code` (`bill_code`),
  KEY `bill_contract_id` (`bill_contract_id`),
  CONSTRAINT `bills_ibfk_1` FOREIGN KEY (`bill_contract_id`) REFERENCES `contracts` (`contract_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `business_lines`;
CREATE TABLE `business_lines` (
  `line_id` int(11) NOT NULL AUTO_INCREMENT,
  `line_market_id` int(11) DEFAULT NULL,
  `line_code` varchar(50) NOT NULL,
  `line_name` varchar(100) NOT NULL,
  `line_description` text DEFAULT NULL,
  `line_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `line_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`line_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `contract_appendices`;
CREATE TABLE `contract_appendices` (
  `appendix_id` int(11) NOT NULL AUTO_INCREMENT,
  `appendix_contract_id` int(11) NOT NULL,
  `appendix_number` varchar(100) NOT NULL,
  `appendix_name` varchar(255) NOT NULL,
  `appendix_sign_date` date NOT NULL,
  `appendix_effect_date` date NOT NULL,
  `appendix_content` text NOT NULL,
  `appendix_file` varchar(255) DEFAULT NULL,
  `appendix_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `appendix_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`appendix_id`),
  UNIQUE KEY `appendix_number` (`appendix_number`),
  KEY `appendix_contract_id` (`appendix_contract_id`),
  CONSTRAINT `contract_appendices_ibfk_1` FOREIGN KEY (`appendix_contract_id`) REFERENCES `contracts` (`contract_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `contract_history`;
CREATE TABLE `contract_history` (
  `history_id` int(11) NOT NULL AUTO_INCREMENT,
  `history_contract_id` int(11) NOT NULL,
  `history_action` varchar(50) NOT NULL,
  `history_changes` text DEFAULT NULL,
  `history_note` text DEFAULT NULL,
  `history_user_id` int(11) DEFAULT NULL,
  `history_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`history_id`),
  KEY `history_contract_id` (`history_contract_id`),
  CONSTRAINT `contract_history_ibfk_1` FOREIGN KEY (`history_contract_id`) REFERENCES `contracts` (`contract_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `contracts`;
CREATE TABLE `contracts` (
  `contract_id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_trader_id` int(11) NOT NULL,
  `contract_stall_id` int(11) NOT NULL,
  `contract_number` varchar(100) NOT NULL,
  `contract_name` varchar(255) NOT NULL,
  `contract_description` text DEFAULT NULL,
  `contract_file` varchar(255) DEFAULT NULL,
  `contract_sign_date` date DEFAULT NULL,
  `contract_start_date` date NOT NULL,
  `contract_end_date` date NOT NULL,
  `contract_deposit` decimal(15,2) NOT NULL DEFAULT 0.00,
  `contract_status_id` int(11) NOT NULL DEFAULT 11,
  `contract_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `contract_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`contract_id`),
  UNIQUE KEY `contract_number` (`contract_number`),
  KEY `contract_trader_id` (`contract_trader_id`),
  KEY `contract_status_id` (`contract_status_id`),
  KEY `idx_contracts_stall` (`contract_stall_id`),
  CONSTRAINT `contracts_ibfk_1` FOREIGN KEY (`contract_trader_id`) REFERENCES `traders` (`trader_id`),
  CONSTRAINT `contracts_ibfk_2` FOREIGN KEY (`contract_stall_id`) REFERENCES `stalls` (`stall_id`),
  CONSTRAINT `contracts_ibfk_3` FOREIGN KEY (`contract_status_id`) REFERENCES `system_statuses` (`status_id`)
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `document_types`;
CREATE TABLE `document_types` (
  `doc_type_id` int(11) NOT NULL AUTO_INCREMENT,
  `doc_type_market_id` int(11) DEFAULT NULL,
  `doc_type_code` varchar(50) NOT NULL,
  `doc_type_name` varchar(100) NOT NULL,
  `doc_type_description` text DEFAULT NULL,
  `doc_type_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `doc_type_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`doc_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `food_safety_inspections`;
CREATE TABLE `food_safety_inspections` (
  `inspection_id` int(11) NOT NULL AUTO_INCREMENT,
  `inspection_title` varchar(255) NOT NULL,
  `inspection_team` varchar(255) NOT NULL,
  `inspection_planned_date` date NOT NULL,
  `inspection_actual_date` date DEFAULT NULL,
  `inspection_status` varchar(20) NOT NULL DEFAULT 'planned',
  `inspection_notes` text DEFAULT NULL,
  `inspection_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `inspection_market_id` int(11) NOT NULL,
  PRIMARY KEY (`inspection_id`),
  KEY `idx_inspections_market` (`inspection_market_id`),
  CONSTRAINT `fk_inspections_market` FOREIGN KEY (`inspection_market_id`) REFERENCES `markets` (`market_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `food_safety_violations`;
CREATE TABLE `food_safety_violations` (
  `violation_id` int(11) NOT NULL AUTO_INCREMENT,
  `violation_trader_id` int(11) NOT NULL,
  `violation_inspection_id` int(11) DEFAULT NULL,
  `violation_code` varchar(50) NOT NULL,
  `violation_date` date NOT NULL,
  `violation_description` text NOT NULL,
  `violation_penalty_measure` text NOT NULL,
  `violation_status` varchar(20) NOT NULL DEFAULT 'pending',
  `violation_resolved_date` date DEFAULT NULL,
  `violation_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `violation_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`violation_id`),
  UNIQUE KEY `violation_code` (`violation_code`),
  KEY `violation_trader_id` (`violation_trader_id`),
  KEY `violation_inspection_id` (`violation_inspection_id`),
  CONSTRAINT `food_safety_violations_ibfk_1` FOREIGN KEY (`violation_trader_id`) REFERENCES `traders` (`trader_id`) ON DELETE CASCADE,
  CONSTRAINT `food_safety_violations_ibfk_2` FOREIGN KEY (`violation_inspection_id`) REFERENCES `food_safety_inspections` (`inspection_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `income_categories`;
CREATE TABLE `income_categories` (
  `category_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `market_id` int(11) NOT NULL,
  `category_type` enum('income','expense') NOT NULL,
  `category_name` varchar(255) NOT NULL,
  `category_note` varchar(500) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=active, 99=soft deleted',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`category_id`),
  KEY `idx_income_categories_market` (`market_id`,`category_type`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `income_vouchers`;
CREATE TABLE `income_vouchers` (
  `voucher_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `market_id` int(11) NOT NULL,
  `voucher_type` enum('income','expense') NOT NULL,
  `category_id` int(10) unsigned DEFAULT NULL,
  `voucher_date` date NOT NULL,
  `content` varchar(1000) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `document_no` varchar(100) DEFAULT NULL,
  `payer_name` varchar(255) DEFAULT NULL,
  `collector_name` varchar(255) DEFAULT NULL,
  `beneficiary_name` varchar(255) DEFAULT NULL,
  `attachment_path` varchar(500) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=active, 99=soft deleted',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`voucher_id`),
  KEY `idx_income_vouchers_market` (`market_id`,`voucher_type`,`status`,`voucher_date`),
  KEY `fk_income_voucher_category` (`category_id`),
  CONSTRAINT `fk_income_voucher_category` FOREIGN KEY (`category_id`) REFERENCES `income_categories` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `market_contract_configs`;
CREATE TABLE `market_contract_configs` (
  `config_id` int(11) NOT NULL AUTO_INCREMENT,
  `market_id` int(11) NOT NULL,
  `template_name` varchar(150) NOT NULL,
  `gov_agency_1` varchar(150) DEFAULT 'UBND PHƯỜNG KON TUM',
  `gov_agency_2` varchar(150) DEFAULT 'PHÒNG KT,HT&ĐT',
  `contract_title_suffix` varchar(255) DEFAULT 'TẠI CÁC CHỢ HẠNG 3 PHƯỜNG KON TUM',
  `rep_a_header` text DEFAULT NULL,
  `rep_a_name_1` varchar(100) DEFAULT 'Phan Thành Trung',
  `rep_a_position_1` varchar(100) DEFAULT 'Tổ trưởng',
  `rep_a_name_2` varchar(100) DEFAULT 'Trương Thảo Linh',
  `rep_a_position_2` varchar(100) DEFAULT 'Tài chính - Kế Toán',
  `rep_a_address` varchar(255) DEFAULT '342 Nguyễn Huệ, phường Kon Tum, tỉnh Kon Tum',
  `rep_a_phone` varchar(20) DEFAULT '',
  `rep_a_fax` varchar(20) DEFAULT '',
  `rep_a_bank_account` varchar(50) DEFAULT '',
  `rep_a_bank_name` varchar(150) DEFAULT '',
  `legal_grounds` text DEFAULT NULL,
  `is_default` tinyint(1) DEFAULT 0,
  `status_id` int(11) NOT NULL DEFAULT 102,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `payment_due_day` varchar(50) DEFAULT '10',
  `payment_grace_period` varchar(50) DEFAULT '10',
  PRIMARY KEY (`config_id`),
  KEY `market_id` (`market_id`),
  CONSTRAINT `market_contract_configs_ibfk_1` FOREIGN KEY (`market_id`) REFERENCES `markets` (`market_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `market_map_elements`;
CREATE TABLE `market_map_elements` (
  `element_id` int(11) NOT NULL AUTO_INCREMENT,
  `element_market_id` int(11) NOT NULL DEFAULT 1,
  `element_type` varchar(50) NOT NULL,
  `element_name` varchar(100) DEFAULT NULL,
  `element_stall_id` int(11) DEFAULT NULL,
  `element_pos_x` int(11) NOT NULL DEFAULT 100,
  `element_pos_y` int(11) NOT NULL DEFAULT 100,
  `element_width` int(11) NOT NULL DEFAULT 80,
  `element_height` int(11) NOT NULL DEFAULT 60,
  `element_rotation` int(11) NOT NULL DEFAULT 0,
  `element_color` varchar(20) DEFAULT NULL,
  `element_waypoints` text DEFAULT NULL,
  `element_stroke_width` int(11) DEFAULT 24,
  `element_latitude` decimal(10,8) DEFAULT NULL,
  `element_longitude` decimal(11,8) DEFAULT NULL,
  `element_width_m` decimal(5,2) DEFAULT 3.00,
  `element_length_m` decimal(5,2) DEFAULT 3.00,
  `element_coords_gps` text DEFAULT NULL,
  PRIMARY KEY (`element_id`),
  KEY `idx_map_market` (`element_market_id`),
  KEY `idx_element_stall_id` (`element_stall_id`),
  CONSTRAINT `fk_mme_stall` FOREIGN KEY (`element_stall_id`) REFERENCES `stalls` (`stall_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=478 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `market_roles`;
CREATE TABLE `market_roles` (
  `role_id` int(11) NOT NULL AUTO_INCREMENT,
  `role_name` varchar(100) NOT NULL,
  `role_description` varchar(255) DEFAULT NULL,
  `role_permissions` text DEFAULT NULL,
  `status_id` int(11) NOT NULL DEFAULT 104,
  `role_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`role_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `markets`;
CREATE TABLE `markets` (
  `market_id` int(11) NOT NULL AUTO_INCREMENT,
  `market_code` varchar(50) NOT NULL,
  `market_name` varchar(150) NOT NULL,
  `market_phone` varchar(20) DEFAULT NULL,
  `market_email` varchar(100) DEFAULT NULL,
  `market_manager_name` varchar(100) DEFAULT NULL,
  `market_logo` varchar(255) DEFAULT NULL,
  `market_province_id` int(11) DEFAULT NULL,
  `market_district_id` int(11) DEFAULT NULL,
  `market_ward_id` int(11) DEFAULT NULL,
  `market_latitude` decimal(10,8) DEFAULT NULL,
  `market_longitude` decimal(11,8) DEFAULT NULL,
  `market_status_code` varchar(50) DEFAULT 'active',
  `market_created_by` int(11) DEFAULT NULL,
  `market_updated_by` int(11) DEFAULT NULL,
  `market_created_at` datetime DEFAULT current_timestamp(),
  `market_updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `market_map_zoom` int(11) DEFAULT 19,
  PRIMARY KEY (`market_id`),
  UNIQUE KEY `market_code` (`market_code`),
  KEY `idx_market_status` (`market_status_code`),
  KEY `idx_market_location` (`market_province_id`,`market_district_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `receipts_payments`;
CREATE TABLE `receipts_payments` (
  `transaction_id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_code` varchar(50) NOT NULL,
  `transaction_type` varchar(10) NOT NULL,
  `transaction_amount` decimal(15,2) NOT NULL,
  `transaction_date` date NOT NULL,
  `transaction_category` varchar(100) NOT NULL,
  `transaction_note` text DEFAULT NULL,
  `transaction_reference_id` int(11) DEFAULT NULL,
  `transaction_created_by` int(11) NOT NULL,
  `transaction_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `transaction_market_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`transaction_id`),
  UNIQUE KEY `transaction_code` (`transaction_code`),
  KEY `transaction_created_by` (`transaction_created_by`),
  KEY `idx_receipts_market` (`transaction_market_id`),
  CONSTRAINT `fk_receipts_market` FOREIGN KEY (`transaction_market_id`) REFERENCES `markets` (`market_id`),
  CONSTRAINT `receipts_payments_ibfk_1` FOREIGN KEY (`transaction_created_by`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `rental_registrations`;
CREATE TABLE `rental_registrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fullname` varchar(100) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `cccd` varchar(20) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `zone` varchar(100) NOT NULL,
  `area` int(11) DEFAULT NULL,
  `business_line` varchar(255) NOT NULL,
  `note` text DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `stall_registrations`;
CREATE TABLE `stall_registrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fullname` varchar(100) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `cccd` varchar(20) DEFAULT NULL,
  `market_id` int(11) DEFAULT NULL,
  `stall_code` varchar(50) DEFAULT NULL,
  `business_item` varchar(255) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `status` enum('pending','contacted','approved','rejected') DEFAULT 'pending',
  `admin_note` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `stall_types`;
CREATE TABLE `stall_types` (
  `stall_type_id` int(11) NOT NULL AUTO_INCREMENT,
  `stall_type_market_id` int(11) DEFAULT NULL,
  `stall_type_code` varchar(50) NOT NULL,
  `stall_type_name` varchar(100) NOT NULL,
  `stall_type_description` text DEFAULT NULL,
  `stall_type_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `stall_type_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`stall_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `stalls`;
CREATE TABLE `stalls` (
  `stall_id` int(11) NOT NULL AUTO_INCREMENT,
  `stall_area_id` int(11) NOT NULL,
  `stall_code` varchar(50) NOT NULL,
  `stall_type_id` int(11) NOT NULL,
  `stall_area_size` decimal(10,2) NOT NULL,
  `stall_base_price` decimal(15,2) NOT NULL,
  `stall_status_id` int(11) NOT NULL DEFAULT 3,
  `stall_map_coordinate_x` decimal(10,2) DEFAULT NULL,
  `stall_map_coordinate_y` decimal(10,2) DEFAULT NULL,
  `stall_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `stall_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `stall_latitude` decimal(10,8) DEFAULT NULL,
  `stall_longitude` decimal(11,8) DEFAULT NULL,
  PRIMARY KEY (`stall_id`),
  UNIQUE KEY `stall_code` (`stall_code`),
  KEY `stall_status_id` (`stall_status_id`),
  KEY `fk_stalls_type` (`stall_type_id`),
  KEY `idx_stalls_area` (`stall_area_id`),
  CONSTRAINT `fk_stalls_type` FOREIGN KEY (`stall_type_id`) REFERENCES `stall_types` (`stall_type_id`),
  CONSTRAINT `stalls_ibfk_1` FOREIGN KEY (`stall_area_id`) REFERENCES `areas` (`area_id`) ON DELETE CASCADE,
  CONSTRAINT `stalls_ibfk_2` FOREIGN KEY (`stall_status_id`) REFERENCES `system_statuses` (`status_id`)
) ENGINE=InnoDB AUTO_INCREMENT=193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `status_colors`;
CREATE TABLE `status_colors` (
  `color_id` int(11) NOT NULL AUTO_INCREMENT,
  `color_class` varchar(50) NOT NULL,
  `color_description` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`color_id`),
  UNIQUE KEY `color_class` (`color_class`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `system_actors`;
CREATE TABLE `system_actors` (
  `actor_id` int(11) NOT NULL AUTO_INCREMENT,
  `actor_code` varchar(50) NOT NULL,
  `actor_name` varchar(100) NOT NULL,
  `actor_description` text DEFAULT NULL,
  PRIMARY KEY (`actor_id`),
  UNIQUE KEY `actor_code` (`actor_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `system_logs`;
CREATE TABLE `system_logs` (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `log_user_id` int(11) DEFAULT NULL,
  `log_action_type` varchar(50) NOT NULL,
  `log_action_description` text NOT NULL,
  `log_ip_address` varchar(45) DEFAULT NULL,
  `log_user_agent` text DEFAULT NULL,
  `log_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `log_user_id` (`log_user_id`),
  CONSTRAINT `system_logs_ibfk_1` FOREIGN KEY (`log_user_id`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `system_statuses`;
CREATE TABLE `system_statuses` (
  `status_id` int(11) NOT NULL AUTO_INCREMENT,
  `status_domain` varchar(50) NOT NULL,
  `status_code` varchar(50) NOT NULL,
  `status_name` varchar(100) NOT NULL,
  `status_color_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`status_id`),
  UNIQUE KEY `uk_domain_code` (`status_domain`,`status_code`),
  KEY `status_color_id` (`status_color_id`),
  CONSTRAINT `system_statuses_ibfk_1` FOREIGN KEY (`status_color_id`) REFERENCES `status_colors` (`color_id`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `trader_attp`;
CREATE TABLE `trader_attp` (
  `attp_id` int(11) NOT NULL AUTO_INCREMENT,
  `attp_trader_id` int(11) NOT NULL,
  `attp_doc_type_id` int(11) NOT NULL,
  `attp_doc_number` varchar(100) NOT NULL,
  `attp_name` varchar(255) NOT NULL,
  `attp_description` text DEFAULT NULL,
  `attp_file` varchar(255) DEFAULT NULL,
  `attp_status_id` int(11) NOT NULL DEFAULT 18,
  `attp_issuer` varchar(150) DEFAULT NULL,
  `attp_issue_date` date NOT NULL,
  `attp_expiry_date` date NOT NULL,
  `attp_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `attp_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`attp_id`),
  KEY `attp_trader_id` (`attp_trader_id`),
  KEY `attp_status_id` (`attp_status_id`),
  KEY `fk_attp_doc_type` (`attp_doc_type_id`),
  CONSTRAINT `fk_attp_doc_type` FOREIGN KEY (`attp_doc_type_id`) REFERENCES `document_types` (`doc_type_id`),
  CONSTRAINT `trader_attp_ibfk_1` FOREIGN KEY (`attp_trader_id`) REFERENCES `traders` (`trader_id`) ON DELETE CASCADE,
  CONSTRAINT `trader_attp_ibfk_2` FOREIGN KEY (`attp_status_id`) REFERENCES `system_statuses` (`status_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `traders`;
CREATE TABLE `traders` (
  `trader_id` int(11) NOT NULL AUTO_INCREMENT,
  `trader_code` varchar(50) NOT NULL,
  `trader_fullname` varchar(100) NOT NULL,
  `trader_phone` varchar(15) DEFAULT NULL,
  `trader_cccd` varchar(20) DEFAULT NULL,
  `trader_business_line_id` int(11) DEFAULT NULL,
  `trader_address` text DEFAULT NULL,
  `trader_description` text DEFAULT NULL,
  `trader_license_file` text DEFAULT NULL,
  `trader_status_id` int(11) NOT NULL,
  `trader_market_id` int(11) DEFAULT NULL,
  `trader_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `trader_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`trader_id`),
  UNIQUE KEY `trader_code` (`trader_code`),
  UNIQUE KEY `trader_cccd` (`trader_cccd`),
  KEY `trader_status_id` (`trader_status_id`),
  KEY `trader_business_line_id` (`trader_business_line_id`),
  KEY `fk_traders_market` (`trader_market_id`),
  CONSTRAINT `fk_traders_market` FOREIGN KEY (`trader_market_id`) REFERENCES `markets` (`market_id`) ON DELETE SET NULL,
  CONSTRAINT `traders_ibfk_1` FOREIGN KEY (`trader_status_id`) REFERENCES `system_statuses` (`status_id`),
  CONSTRAINT `traders_ibfk_2` FOREIGN KEY (`trader_business_line_id`) REFERENCES `business_lines` (`line_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_market_permissions`;
CREATE TABLE `user_market_permissions` (
  `permission_id` int(11) NOT NULL AUTO_INCREMENT,
  `permission_user_id` int(11) NOT NULL,
  `permission_market_id` int(11) NOT NULL,
  `permission_module_code` varchar(50) NOT NULL,
  `permission_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`permission_id`),
  UNIQUE KEY `uk_user_market_module` (`permission_user_id`,`permission_market_id`,`permission_module_code`),
  KEY `permission_market_id` (`permission_market_id`),
  CONSTRAINT `user_market_permissions_ibfk_1` FOREIGN KEY (`permission_user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `user_market_permissions_ibfk_2` FOREIGN KEY (`permission_market_id`) REFERENCES `markets` (`market_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_markets`;
CREATE TABLE `user_markets` (
  `user_market_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_market_user_id` int(11) NOT NULL,
  `user_market_market_id` int(11) NOT NULL,
  `user_market_role_id` int(11) NOT NULL,
  `user_market_created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`user_market_id`),
  UNIQUE KEY `uk_user_market_role` (`user_market_user_id`,`user_market_market_id`,`user_market_role_id`),
  KEY `user_market_market_id` (`user_market_market_id`),
  KEY `user_market_role_id` (`user_market_role_id`),
  KEY `idx_user_markets_query` (`user_market_user_id`,`user_market_market_id`),
  CONSTRAINT `user_markets_ibfk_1` FOREIGN KEY (`user_market_user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `user_markets_ibfk_2` FOREIGN KEY (`user_market_market_id`) REFERENCES `markets` (`market_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `user_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_username` varchar(50) NOT NULL,
  `user_password` varchar(255) NOT NULL,
  `user_fullname` varchar(100) NOT NULL,
  `user_email` varchar(100) DEFAULT NULL,
  `user_is_active` tinyint(1) NOT NULL DEFAULT 1,
  `user_reset_token` varchar(255) DEFAULT NULL,
  `user_reset_expires_at` datetime DEFAULT NULL,
  `user_group` int(11) NOT NULL DEFAULT 2,
  `user_actor_id` int(11) NOT NULL,
  `user_status` int(1) NOT NULL,
  `user_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `user_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `username` (`user_username`),
  KEY `fk_users_actor` (`user_actor_id`),
  CONSTRAINT `fk_users_actor` FOREIGN KEY (`user_actor_id`) REFERENCES `system_actors` (`actor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `utility_readings`;
CREATE TABLE `utility_readings` (
  `reading_id` int(11) NOT NULL AUTO_INCREMENT,
  `reading_stall_id` int(11) NOT NULL,
  `reading_date` date NOT NULL,
  `reading_electric_old` int(11) NOT NULL,
  `reading_electric_new` int(11) NOT NULL,
  `reading_water_old` int(11) NOT NULL,
  `reading_water_new` int(11) NOT NULL,
  `reading_created_by` int(11) NOT NULL,
  `reading_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`reading_id`),
  KEY `reading_stall_id` (`reading_stall_id`),
  KEY `reading_created_by` (`reading_created_by`),
  CONSTRAINT `utility_readings_ibfk_1` FOREIGN KEY (`reading_stall_id`) REFERENCES `stalls` (`stall_id`) ON DELETE CASCADE,
  CONSTRAINT `utility_readings_ibfk_2` FOREIGN KEY (`reading_created_by`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `web_roles`;
CREATE TABLE `web_roles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_name` varchar(150) NOT NULL,
  `role_code` varchar(50) NOT NULL,
  `permissions` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `status` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `role_code` (`role_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `web_users`;
CREATE TABLE `web_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `fullname` varchar(100) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `role` enum('admin','editor') NOT NULL DEFAULT 'editor',
  `permissions` text DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_about_sections`;
CREATE TABLE `website_about_sections` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_title` varchar(255) NOT NULL,
  `section_content` text NOT NULL,
  `section_order` int(11) DEFAULT 1,
  `status` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_banners`;
CREATE TABLE `website_banners` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `banner_title` varchar(255) NOT NULL,
  `banner_description` text DEFAULT NULL,
  `banner_image` varchar(500) NOT NULL,
  `banner_link` varchar(500) DEFAULT NULL,
  `banner_page` enum('home','about','all') DEFAULT 'home',
  `banner_order` int(11) NOT NULL DEFAULT 0,
  `banner_status` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_downloads`;
CREATE TABLE `website_downloads` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `doc_title` varchar(255) NOT NULL,
  `doc_file` varchar(500) NOT NULL,
  `doc_description` text DEFAULT NULL,
  `doc_downloads_count` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_feedbacks`;
CREATE TABLE `website_feedbacks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(50) DEFAULT 'feedback',
  `title` varchar(255) DEFAULT 'Góp ý phản ánh',
  `fb_fullname` varchar(100) NOT NULL,
  `fb_phone` varchar(20) NOT NULL,
  `fb_email` varchar(100) DEFAULT NULL,
  `fb_content` text NOT NULL,
  `reply_content` text DEFAULT NULL,
  `fb_status` tinyint(4) NOT NULL DEFAULT 0,
  `status` varchar(50) DEFAULT 'new',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_posts`;
CREATE TABLE `website_posts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_title` varchar(255) NOT NULL,
  `post_slug` varchar(255) NOT NULL,
  `post_summary` text DEFAULT NULL,
  `post_content` longtext NOT NULL,
  `post_image` varchar(500) DEFAULT NULL,
  `post_status` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_post_slug` (`post_slug`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_settings`;
CREATE TABLE `website_settings` (
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `website_stats`;
CREATE TABLE `website_stats` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `stat_key` varchar(50) NOT NULL,
  `stat_value` bigint(20) NOT NULL DEFAULT 0,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_stat_key` (`stat_key`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
