INSERT INTO `website_about_sections` (`id`, `section_title`, `section_content`, `section_order`, `status`, `created_at`) VALUES ('1', 'Lịch sử hình thành & Phát triển', 'Hình thành từ năm 1985, chợ Trung Tâm Thành Phố là đầu mối buôn bán sầm uất, quy tụ hàng nghìn tiểu thương thuộc nhiều ngành hàng khác nhau, đồng hành cùng quá trình chuyển đổi số của địa phương. Trải qua hơn 40 năm hoạt động và phát triển, chợ đã thực hiện 3 lần cải tạo lớn nâng cấp toàn bộ hệ thống cơ sở hạ tầng, đáp ứng nhu cầu giao thương an toàn, văn minh của nhân dân.', '1', '1', '2026-08-14 18:21:08');
INSERT INTO `website_about_sections` (`id`, `section_title`, `section_content`, `section_order`, `status`, `created_at`) VALUES ('2', 'Quy mô hoạt động', 'Với tổng diện tích hơn 12.000m², Chợ được quy hoạch bài bản thành 8 phân khu chức năng riêng biệt nhằm đảm bảo vệ sinh an toàn thực phẩm và trật tự kinh doanh. Hiện chợ có 1.240 sạp kinh doanh hoạt động ổn định, cung cấp đầy đủ các mặt hàng thiết yếu cho đời sống người dân.', '2', '1', '2026-08-14 18:21:08');
INSERT INTO `website_about_sections` (`id`, `section_title`, `section_content`, `section_order`, `status`, `created_at`) VALUES ('3', 'Ngành hàng kinh doanh chính', 'Thực phẩm tươi sống: Rau củ quả, thịt cá tươi sống được kiểm định chất lượng mỗi ngày.\r\nBách hóa & Đồ gia dụng: Đầy đủ các mặt hàng tiêu dùng thiết yếu phục vụ đời sống gia đình.\r\nThời trang & Mỹ phẩm: Quần áo, giày dép, phụ kiện đa dạng về mẫu mã và giá cả hợp lý.\r\nKhu ẩm thực & Dịch vụ ăn uống: Nơi hội tụ các món ăn truyền thống vùng miền đạt chuẩn vệ sinh an toàn thực phẩm.', '3', '1', '2026-08-14 18:21:08');
INSERT INTO `website_about_sections` (`id`, `section_title`, `section_content`, `section_order`, `status`, `created_at`) VALUES ('4', 'Định hướng số hóa 2026', 'Thực hiện chủ trương chuyển đổi số của Thành phố, Ban quản lý Chợ đang nỗ lực số hóa 100% sơ đồ sạp chợ, hỗ trợ đăng ký thuê sạp trực tuyến, tra cứu thông tin tiểu thương minh bạch và thúc đẩy thanh toán không dùng tiền mặt (chợ 4.0), mang lại trải nghiệm tiện ích nhất cho cả người bán lẫn người mua.', '4', '1', '2026-08-14 18:21:08');
INSERT INTO `website_banners` (`id`, `banner_title`, `banner_description`, `banner_image`, `banner_link`, `banner_page`, `banner_order`, `banner_status`, `created_at`) VALUES ('1', 'Cổng thông tin Chợ Quảng Ngãi', 'Tra cứu sơ đồ chợ, tìm kiếm vị trí sạp, xem thông tin tiểu thương và đăng ký thuê sạp trực tuyến — nhanh chóng, minh bạch, mọi lúc mọi nơi. haha', 'https://images.unsplash.com/photo-1542838132-92c53300491e?q=80&w=1200', 'home/map', 'home', '1', '1', '2026-08-12 00:22:42');
INSERT INTO `website_banners` (`id`, `banner_title`, `banner_description`, `banner_image`, `banner_link`, `banner_page`, `banner_order`, `banner_status`, `created_at`) VALUES ('2', 'Đăng ký thuê sạp trực tuyến nhanh chóng', 'Tra cứu sơ đồ chợ, tìm kiếm vị trí sạp, xem thông tin tiểu thương và đăng ký thuê sạp trực tuyến — nhanh chóng, minh bạch, mọi lúc mọi nơi.', 'https://images.unsplash.com/photo-1533900298318-6b8da08a523e?q=80&w=1200', 'home/register', 'about', '2', '1', '2026-08-12 00:22:42');
INSERT INTO `website_feedbacks` (`id`, `type`, `title`, `fb_fullname`, `fb_phone`, `fb_email`, `fb_content`, `reply_content`, `fb_status`, `status`, `created_at`) VALUES ('1', 'feedback', 'Góp ý hệ thống chiếu sáng khu B', 'Lê Văn C', '0905111222', 'levanc@gmail.com', 'Khu B buổi tối hơi tối, đề nghị BQL bổ sung thêm đèn chiếu sáng.', 'BQL đã tiếp nhận và giải quyết xong.', '3', 'resolved', '2026-08-14 16:54:45');
