INSERT INTO `website_posts` (`id`, `post_title`, `post_slug`, `post_summary`, `post_content`, `post_image`, `post_status`, `created_at`, `updated_at`) VALUES ('1', 'Thông báo về việc đăng ký thuê sạp đợt 2/2026 tại Chợ Trung Tâm', 'thong-bao-dang-ky-thue-sap-dot-2-2026', 'Ban quản lý Chợ Trung Tâm thông báo tiếp nhận hồ sơ đăng ký thuê sạp thương mại đợt 2 bắt đầu từ ngày 15/08/2026.', 'Ban quản lý Chợ Trung Tâm xin thông báo đến toàn thể bà con tiểu thương và nhân dân về việc tiếp nhận đăng ký thuê các vị trí sạp kinh doanh đợt 2 năm 2026. Các ngành hàng bao gồm thời trang, thực phẩm sạch và ẩm thực. Mọi thông tin chi tiết xin liên hệ trực tiếp văn phòng Ban quản lý hoặc nộp đơn trực tuyến qua cổng đăng ký.', 'https://images.unsplash.com/photo-1595535373192-1697a7ab1ff1?q=80&w=600', '1', '2026-08-12 00:22:42', '2026-08-12 00:22:42');
INSERT INTO `website_posts` (`id`, `post_title`, `post_slug`, `post_summary`, `post_content`, `post_image`, `post_status`, `created_at`, `updated_at`) VALUES ('2', 'Kế hoạch kiểm tra vệ sinh an toàn thực phẩm quý 3/2026', 'ke-hoach-kiem-tra-vsattp-quy-3-2026', 'Phối hợp với Sở Y tế thực hiện thanh kiểm tra định kỳ các hộ kinh doanh thực phẩm tươi sống.', 'Để đảm bảo sức khỏe cho người tiêu dùng và giữ vững chất lượng dịch vụ của chợ, Ban quản lý phối hợp cùng đoàn liên ngành của Chi cục VSATTP tỉnh Quảng Ngãi sẽ tiến hành thanh kiểm tra định kỳ các hộ kinh doanh ngành hàng thực phẩm tươi sống, ăn uống từ ngày 20/08/2026. Đề nghị các hộ chuẩn bị đầy đủ hồ sơ khám sức khỏe và cam kết đảm bảo vệ sinh.', 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?q=80&w=600', '1', '2026-08-12 00:22:42', '2026-08-14 19:22:23');
INSERT INTO `website_posts` (`id`, `post_title`, `post_slug`, `post_summary`, `post_content`, `post_image`, `post_status`, `created_at`, `updated_at`) VALUES ('3', 'Thông báo lịch tổng vệ sinh và phun khử trùng toàn chợ tháng 8/2026', 'thong-bao-lich-tong-ve-sinh-thang-8-2027', 'Ban Quản lý Chợ thông báo kế hoạch tổng vệ sinh, khử trùng định kỳ các khu vực ngành hàng tươi sống và bách hóa.', '<p>Kính gửi quý bà con tiểu thương và nhân dân tham gia mua bán tại <b>Chợ Trung Tâm Thành Phố</b>,</p>\r\n<h2>1. Mục đích & Kế hoạch triển khai</h2>\r\n<p>Nhằm đảm bảo <i>vệ sinh môi trường</i> và an toàn thực phẩm, Ban Quản Lý chợ sẽ tiến hành tổng vệ sinh và tiêu độc khử trùng định kỳ.</p>\r\n<ul>\r\n    <li><b>Thời gian bắt đầu:</b> 18h00 ngày Chủ Nhật (24/08/2026).</li>\r\n    <li><b>Khu vực thực hiện:</b> Toàn bộ Khu A, B, C và D.</li>\r\n</ul>\r\n<h2>2. Yêu cầu đối với Tiểu thương</h2>\r\nĐề nghị các hộ kinh doanh thu dọn hàng hóa, rác thải và che đậy cẩn thận trước thời gian trên.', 'https://images.unsplash.com/photo-1542838132-92c53300491e?q=80&w=800', '1', '2026-08-14 19:22:43', '2026-08-19 18:13:23');
INSERT INTO `website_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('about_business_lines', 'Thực phẩm tươi sống: Rau củ quả, thịt cá tươi sống được kiểm định chất lượng mỗi ngày.\r\nBách hóa & Đồ gia dụng: Đầy đủ các mặt hàng tiêu dùng thiết yếu phục vụ đời sống gia đình.\r\nThời trang & Mỹ phẩm: Quần áo, giày dép, phụ kiện đa dạng về mẫu mã và giá cả hợp lý.\r\nKhu ẩm thực & Dịch vụ ăn uống: Nơi hội tụ các món ăn truyền thống vùng miền đạt chuẩn vệ sinh an toàn thực phẩm..', '2026-08-14 18:20:12');
INSERT INTO `website_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('about_digitization', 'Thực hiện chủ trương chuyển đổi số của Thành phố, Ban quản lý Chợ đang nỗ lực số hóa 100% sơ đồ sạp chợ, hỗ trợ đăng ký thuê sạp trực tuyến, tra cứu thông tin tiểu thương minh bạch và thúc đẩy thanh toán không dùng tiền mặt (chợ 4.0), mang lại trải nghiệm tiện ích nhất cho cả người bán lẫn người mua..', '2026-08-14 18:20:12');
INSERT INTO `website_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('about_history', 'Hình thành từ năm 1985, chợ Trung Tâm Thành Phố là đầu mối buôn bán sầm uất, quy tụ hàng nghìn tiểu thương thuộc nhiều ngành hàng khác nhau, đồng hành cùng quá trình chuyển đổi số của địa phương. Trải qua hơn 40 năm hoạt động và phát triển, chợ đã thực hiện 3 lần cải tạo lớn nâng cấp toàn bộ hệ thống cơ sở hạ tầng, đáp ứng nhu cầu giao thương an toàn, văn minh của nhân dân..', '2026-08-14 18:20:12');
INSERT INTO `website_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('about_scale', 'Với tổng diện tích hơn 12.000m², Chợ được quy hoạch bài bản thành 8 phân khu chức năng riêng biệt nhằm đảm bảo vệ sinh an toàn thực phẩm và trật tự kinh doanh. Hiện chợ có 1.240 sạp kinh doanh hoạt động ổn định, cung cấp đầy đủ các mặt hàng thiết yếu cho đời sống người dân..', '2026-08-14 18:20:12');
