INSERT INTO `website_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES ('home_intro_points', '[{\"title\":\"Lịch sử hình thành\",\"desc\":\"Xây dựng từ năm 1985, trải qua 3 lần cải tạo nâng cấp.\"},{\"title\":\"Quy mô\",\"desc\":\"8 khu vực, 1.240 sạp kinh doanh trên 12.000m².\"},{\"title\":\"Vai trò địa phương\",\"desc\":\"Cung ứng hàng hóa thiết yếu cho hơn 50.000 hộ dân.\"},{\"title\":\"Ngành hàng kinh doanh\",\"desc\":\"Thực phẩm tươi sống, bách hóa, thời trang, ẩm thực.\"},{\"title\":\"Mục tiêu chuyển đổi số\",\"desc\":\"Số hóa 100% sơ đồ sạp và thủ tục đăng ký trực tuyến.\"},{\"title\":\"An toàn thực phẩm\",\"desc\":\"Kiểm định nguồn gốc xuất xứ nghiêm ngặt định kỳ hàng tuần.\"}]', '2026-08-14 20:42:53');
